1	use crate::actions::Target;
2	use crate::cards::CardRegistry;
3	use crate::events::GameEvent;
4	use crate::state::{GameState, LogLevel, StackEntry};
5	use crate::types::Zone;
6	
7	/// Check if a target is still legal at resolution time.
8	fn is_target_legal(state: &GameState, target: &Target, target_req: &crate::cards::TargetRequirement) -> bool {
9	    use crate::cards::TargetRequirement;
10	
11	    // ModalChoice: legal if legal under any mode.
12	    if let TargetRequirement::ModalChoice(ref modes) = target_req {
13	        return modes.iter().any(|mode_req| is_target_legal(state, target, mode_req));
14	    }
15	
16	    // Unwrap nested requirements (UpToTargets, TwoTargets).
17	    let inner_req = match target_req {
18	        TargetRequirement::UpToTargets(_, inner) => inner.as_ref(),
19	        TargetRequirement::TwoTargets(inner, _) => inner.as_ref(),
20	        other => other,
21	    };
22	    match target {
23	        Target::Object(id) => {
24	            match state.get_object(*id) {
25	                Some(obj) => {
26	                    match inner_req {
27	                        TargetRequirement::GraveyardCard
28	                        | TargetRequirement::GraveyardCreature
29	                        | TargetRequirement::GraveyardCreatureOfSubtype(_)
30	                        | TargetRequirement::GraveyardCardOwnedByCaster
31	                        | TargetRequirement::GraveyardCardOwnedByOpponent => obj.zone == Zone::Graveyard,
32	                        TargetRequirement::ExileCard => obj.zone == Zone::Exile,
33	                        _ => obj.zone == Zone::Battlefield || obj.zone == Zone::Stack,
34	                    }
35	                }
36	                None => false,
37	            }
38	        }
39	        Target::Player(_) => true,
40	    }
41	}
42	
43	/// Resolve the top item on the stack (spell or trigger).
44	///
45	/// For spells: checks target legality (CR 608.2b fizzle), calls on_resolve.
46	/// For triggers: delegates to triggers::resolve_next_trigger.
47	pub fn resolve_top_of_stack(state: &mut GameState, registry: &CardRegistry) {
48	    let entry = match state.stack.last() {
49	        Some(e) => e.clone(),
50	        None => return,
51	    };
52	
53	    match entry {
54	        StackEntry::Trigger(_) => {
55	            // Trigger resolution is handled by the triggers module.
56	            crate::triggers::resolve_next_trigger(state, registry);
57	        }
58	        StackEntry::Spell(object_id) => {
59	            state.stack.pop(); // Remove the spell from the stack.
60	            resolve_spell(state, registry, object_id);
61	        }
62	    }
63	}
64	
65	/// Resolve a spell from the stack.
66	fn resolve_spell(state: &mut GameState, registry: &CardRegistry, object_id: crate::ids::ObjectId) {
67	    let (card_id, targets) = match state.get_object(object_id) {
68	        Some(obj) => (obj.card_id, obj.targets.clone()),
69	        None => return,
70	    };
71	
72	    let name = registry.card_data(card_id).map(|d| d.name).unwrap_or_else(|| "?".into());
73	
74	    // CR 608.2b: Check target legality. If the spell has targets and ALL
75	    // are illegal, it's countered by game rules (fizzled).
76	    let target_req = registry.get(card_id)
77	        .map(|b| b.target_requirement())
78	        .unwrap_or(crate::cards::TargetRequirement::None);
79	    if !targets.is_empty() {
80	        let any_legal = targets.iter().any(|t| is_target_legal(state, t, &target_req));
81	        if !any_legal {
82	            state.log(LogLevel::Event, format!("{} fizzled (all targets illegal)", name));
83	            // Move to graveyard (or exile for flashback) without resolving.
84	            state.move_spell_after_resolve(object_id);
85	            return;
86	        }
87	    }
88	
89	    // Spell resolves normally.
90	    state.log(LogLevel::Event, format!("{} resolved", name));
91	    state.events.push(GameEvent::SpellResolved { object: object_id });
92	
93	    // Call the card's on_resolve behavior with targets.
94	    if let Some(behavior) = registry.get(card_id) {
95	        behavior.on_resolve(state, object_id, &targets, registry);
96	    }
97	
98	    // If the card set an awaiting_action, it's mid-resolution (e.g., Unburial
99	    // Rites waiting for player to choose a creature). Don't clean up yet —
100	    // the ResolveChoice handler in submit_action will do that.
101	    if state.awaiting_action.is_some() {
102	        return;
103	    }
104	
105	    // If the card is still on the stack after resolution, move it to the
106	    // appropriate zone. Flashback spells go to exile; others to graveyard.
107	    if let Some(obj) = state.get_object(object_id) {
108	        if obj.zone == Zone::Stack {
109	            state.move_spell_after_resolve(object_id);
110	        }
111	    }
112	}
